"""Build Barmil's portable, crawlable static site. Python standard library only."""
import json, os, shutil, html, re, hashlib
from urllib.parse import urlparse
from pathlib import Path
from xml.sax.saxutils import escape as xml_escape

ROOT=Path(__file__).resolve().parent
OUTPUT_NAME=os.environ.get('BUILD_OUTPUT_NAME','dist')
if OUTPUT_NAME not in ('dist','.audit-production'): raise ValueError('Unsupported build output directory')
OUT=ROOT/OUTPUT_NAME
DATA=json.loads((ROOT/'content.json').read_text())
B=DATA['business']; SERVICES=DATA['services']; BY_SLUG={s['slug']:s for s in SERVICES}
ORIGIN=os.environ.get('SITE_URL',B['website']).rstrip('/')
LIVE_ENQUIRY=os.environ.get('ENQUIRY_URL',B['website']+'/contact')
PREVIEW=os.environ.get('SITE_PREVIEW','1')=='1'
FORM_BACKEND=os.environ.get('FORM_BACKEND','external')
TARGETS={t['path']:t for t in json.loads((ROOT/'seo-targets.json').read_text())}
IMAGE_INFO={
 'hero-home-support.webp':(1200,900,'A wheelchair user and another woman smiling together at home'),
 'about-support-team.webp':(1024,1024,'Two women sitting together at a dining table'),
 'community-picnic.webp':(1200,900,'A group, including a wheelchair user, sharing a meal outdoors'),
 'transport-assistance.webp':(1200,900,'A man assisting a wheelchair user inside a van')
}

e=lambda value:html.escape(str(value),quote=True)

paths={
 'arrow':'<path d="M5 12h14M13 6l6 6-6 6"/>',
 'chevron':'<path d="m6 9 6 6 6-6"/>',
 'home':'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1Z"/><path d="M9 21v-8h6v8"/>',
 'heart':'<path d="M20.5 4.8a5.5 5.5 0 0 0-7.8 0l-.7.8-.7-.8a5.5 5.5 0 0 0-7.8 7.8L12 21l8.5-8.4a5.5 5.5 0 0 0 0-7.8Z"/>',
 'people':'<circle cx="9" cy="7" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M17 4a3 3 0 0 1 0 6M21 21v-3a6 6 0 0 0-3-5"/>',
 'grow':'<path d="M12 21v-9M12 16C5 16 3 12 3 7c6 0 9 3 9 9ZM12 12c0-6 3-9 9-9 0 6-3 9-9 9Z"/>',
 'car':'<path d="m3 10 2-6h14l2 6v9H3ZM3 11h18M6 19v2M18 19v2"/><path d="M6 15h2M16 15h2"/>',
 'key':'<circle cx="8" cy="8" r="5"/><path d="m12 12 9 9M16 16l3-3M18 18l3-3"/>',
 'spark':'<path d="m12 3 2.4 6.6L21 12l-6.6 2.4L12 21l-2.4-6.6L3 12l6.6-2.4ZM20 3v4M18 5h4"/>',
 'path':'<circle cx="5" cy="5" r="2"/><circle cx="19" cy="19" r="2"/><path d="M5 7v5a4 4 0 0 0 4 4h6M12 4h7v7M19 4l-9 9"/>',
 'sun':'<circle cx="12" cy="12" r="4"/><path d="M12 2v2M12 20v2M2 12h2M20 12h2M5 5l1 1M18 18l1 1M5 19l1-1M18 6l1-1"/>',
 'chat':'<path d="M21 11a9 9 0 0 1-9 9 10 10 0 0 1-4-.8L3 21l1.7-5A9 9 0 1 1 21 11Z"/><path d="M8 10h8M8 14h5"/>',
 'check':'<path d="m5 12 4 4L19 6"/><circle cx="12" cy="12" r="10"/>',
 'phone':'<path d="m4 3 4 1 1 5-2 2c2 3 3 4 6 6l2-2 5 1 1 4c-1 3-6 2-10-1S1 7 4 3Z"/>',
 'pin':'<path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 0 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/>',
 'menu':'<path d="M3 6h18M3 12h18M3 18h18"/>'
}
def icon(name,cls=''):
 return f'<svg viewBox="0 0 24 24" aria-hidden="true" class="icon {cls}">{paths.get(name,paths["heart"])}</svg>'
def link(path,text,cls='',arrow=False):
 return f'<a href="{e(path)}" class="{cls}">{e(text)}{icon("arrow","arrow") if arrow else ""}</a>'
def brand():
 return '<a class="brand" href="/" aria-label="Barmil Care Services home"><img src="/assets/barmil-logo.png" width="56" height="56" alt=""><span>Barmil Care Services<small>SUPPORTING CANBERRA</small></span></a>'
def service_url(s): return '/services/'+s['slug']
def header(current):
 def nav(path,label):return f'<a href="{path}"'+(' aria-current="page"' if current==path else '')+f'>{label}</a>'
 return f'''<a class="skip" href="#main">Skip to content</a><div class="topbar"><div class="container"><span>NDIS & disability support across Canberra</span><span class="topbar-hours">{e(B['hours'])}</span><a href="tel:{B['phoneHref']}">{B['phone']}</a></div></div>
 <header class="site-header"><div class="container nav-wrap">{brand()}<button class="mobile-toggle" aria-label="Toggle navigation" aria-controls="main-nav" aria-expanded="false">{icon('menu')}</button><nav class="main-nav" id="main-nav" aria-label="Main navigation">{nav('/about','About us')}<div class="nav-service">{nav('/services','Our services')}<button class="dropdown-toggle" aria-label="Show service pages" aria-expanded="false" aria-controls="service-menu">{icon('chevron')}</button><div class="dropdown" id="service-menu" hidden>{''.join(link(service_url(s),s['name']) for s in SERVICES)}{link('/services','Explore all services','all-services',True)}</div></div>{nav('/service-areas','Canberra areas')}{nav('/ndis-supports','NDIS guide')}{nav('/contact','Contact')}</nav>{link('/contact','Let’s talk','btn nav-cta',True)}</div></header>'''
def footer():
 return f'''<section class="cta-band"><div class="container cta-inner"><div><h2>Let’s start with what matters to you.</h2><p>Tell us about your goals, your routine and the support you’re looking for.</p></div><div class="actions">{link('/contact','Talk to Barmil','btn',True)}{link('tel:'+B['phoneHref'],B['phone'],'btn secondary')}</div></div></section><footer class="site-footer"><div class="container"><div class="footer-grid"><div class="footer-brand">{brand()}<p>Practical support at home and in the community. Built around your life, across Canberra.</p></div><div><div class="footer-title">Our services</div><div class="footer-links">{''.join(link(service_url(s),s['short']) for s in SERVICES)}</div></div><div><div class="footer-title">Explore</div><div class="footer-links">{''.join(link(a,b) for a,b in [('/about','About Barmil'),('/services','All services'),('/service-areas','Canberra service areas'),('/ndis-supports','Understanding your supports'),('/faqs','Your questions'),('/contact','Contact us')])}</div></div><div><div class="footer-title">Get in touch</div><div class="footer-links">{link('tel:'+B['phoneHref'],B['phone'])}{link('mailto:'+B['email'],B['email'])}<span class="muted" style="font-size:.77rem">Canberra, ACT<br>{B['hours']}</span></div></div></div><div class="footer-bottom"><span>© 2026 Barmil Care Services. All rights reserved.</span><span>{link('/privacy','Privacy')} · Your choices. Your community.</span></div></div></footer><div class="mobile-call">{link('tel:'+B['phoneHref'],'Call Barmil','btn secondary')}{link('/contact','Make an enquiry','btn')}</div>'''
def breadcrumbs(items):
 return '<div class="container breadcrumbs">'+link('/','Home')+''.join('<span aria-hidden="true">/</span>'+ (link(path,label) if path else f'<span>{e(label)}</span>') for path,label in items)+'</div>'
def faq_html(faqs):
 return '<div class="faq-list">'+''.join(f'<details><summary>{e(q)}</summary><p>{e(a)}</p></details>' for q,a in faqs)+'</div>'
def card(s):
 return f'''<a class="service-card" href="{service_url(s)}" data-category="{e(s['category'])}"><span class="icon-box">{icon(s['icon'])}</span><h3>{e(s['name'])}</h3><p>{e(s.get('cardSummary',s['intro'].split('. ')[0]+'.'))}</p><span class="card-link">Explore this support {icon('arrow','arrow')}</span></a>'''
def compact_hero(title,eyebrow,intro):
 return f'<section class="container page-hero compact"><div class="eyebrow">{e(eyebrow)}</div><h1>{e(title)}</h1><p class="lead">{e(intro)}</p></section>'
def cta_actions(label='Talk about your support'):
 return f'<div class="actions">{link("/contact",label,"btn",True)}{link("tel:"+B["phoneHref"],B["phone"],"btn secondary")}</div>'
GLOBAL_FAQS=[
 ('Which parts of Canberra do you serve?','Barmil serves Canberra, including Belconnen, Gungahlin, North and South Canberra, Woden Valley, Weston Creek, Tuggeranong and the Molonglo Valley. Tell us your suburb so we can discuss suitable arrangements and availability.'),
 ('How do I start receiving support?','Call, email or use the enquiry form to tell us about your goals, the support you need and your Canberra suburb. We will discuss suitability, funding arrangements and availability before agreeing on services.'),
 ('Can I choose the support I receive?','Your goals and preferences guide the discussion. You can ask about one service or a combination, then agree on a support arrangement that is suitable for your needs.'),
 ('Will my NDIS plan cover these services?','The answer depends on your plan, your disability-related needs and the service being proposed. Check your funding and payment arrangements before agreeing to support.'),
 ('Can a family member or support coordinator contact you?','Yes. A person you choose can help make the enquiry or join the discussion. We will clarify your preferences and consent before sharing information or making arrangements.'),
 ('Can I ask about changing providers?','Yes. Tell us the support you are looking for and any timing considerations. Check notice periods and existing service agreements before making a change.'),
 ('Do you provide overnight or 24-hour care?','These arrangements must be discussed individually. They are not assumed to be included in daily tasks or shared living assistance.'),
 ('Do you support every NDIS funding arrangement?','Please tell us how your plan is managed. We will confirm whether the proposed service and payment arrangement can be accepted before you start.'),
 ('Can services change as my needs change?','You can contact us to discuss changes to your goals, routine or support needs. Any changes should be agreed as part of your service arrangements.'),
 ('Are activities, travel and tickets included in the price?','Ask for a clear explanation of support time, travel and any other costs. Ordinary tickets, memberships and meals are different from the support needed to participate.'),
 ('What should I include in my first enquiry?','Your name, preferred contact method, Canberra suburb and a brief description of the service you need are a helpful starting point. Avoid sending sensitive records in an initial enquiry.'),
 ('How do I give feedback?','Call or email Barmil and explain what you would like to discuss. You can involve a support person of your choice and ask about the process for raising a concern.')
]
AREAS=[
 ('Belconnen','Belconnen, Bruce, Kaleen, Hawker, Holt and surrounding suburbs.'),
 ('Gungahlin','Gungahlin, Franklin, Harrison, Ngunnawal, Casey and surrounding suburbs.'),
 ('North Canberra','The city, Braddon, Dickson, Lyneham, Ainslie and surrounding suburbs.'),
 ('South Canberra','Kingston, Griffith, Narrabundah, Red Hill and surrounding suburbs.'),
 ('Woden Valley','Phillip, Curtin, Garran, Mawson, Pearce and surrounding suburbs.'),
 ('Weston Creek','Weston, Duffy, Chapman, Rivett and surrounding suburbs.'),
 ('Tuggeranong','Greenway, Kambah, Wanniassa, Calwell and surrounding suburbs.'),
 ('Molonglo Valley','Coombs, Wright, Denman Prospect and surrounding suburbs.')
]
def org_schema():
 city={'@type':'City','name':'Canberra','containedInPlace':{'@type':'AdministrativeArea','name':'Australian Capital Territory'}}
 return {'@type':'Organization','@id':ORIGIN+'/#organization','name':B['name'],'url':ORIGIN+'/','logo':ORIGIN+'/assets/barmil-logo.png','telephone':B['phoneHref'],'email':B['email'],'areaServed':[city]+[{'@type':'Place','name':a,'containedInPlace':city} for a,b in AREAS],'contactPoint':{'@type':'ContactPoint','contactType':'enquiries','telephone':B['phoneHref'],'email':B['email']}}
PAGES=[]
def write_page(path,title,description,body,crumbs=None,service=None,noindex=False):
 graph=[org_schema(),{'@type':'WebSite','@id':ORIGIN+'/#website','name':B['name'],'url':ORIGIN+'/','inLanguage':'en-AU'}, {'@type':'WebPage','@id':ORIGIN+path+'#webpage','url':ORIGIN+path,'name':title,'description':description,'isPartOf':{'@id':ORIGIN+'/#website'},'inLanguage':'en-AU'}]
 if crumbs:
  items=[{'@type':'ListItem','position':1,'name':'Home','item':ORIGIN+'/'}]
  for n,(u,label) in enumerate(crumbs,2):items.append({'@type':'ListItem','position':n,'name':label,'item':ORIGIN+(u or path)})
  graph.append({'@type':'BreadcrumbList','itemListElement':items})
 if service:graph.append({'@type':'Service','@id':ORIGIN+path+'#service','name':service['h1'],'serviceType':service['name'],'description':service['description'],'url':ORIGIN+path,'provider':{'@id':ORIGIN+'/#organization'},'areaServed':{'@type':'City','name':'Canberra'}})
 graph[2]['about']={'@id':ORIGIN+'/#organization'}
 if service:graph[2]['mainEntity']={'@id':ORIGIN+path+'#service'}
 graph[1]['publisher']={'@id':ORIGIN+'/#organization'}
 robots='noindex, nofollow' if PREVIEW else ('noindex, follow' if noindex else 'index, follow, max-image-preview:large')
 schema_json=json.dumps({'@context':'https://schema.org','@graph':graph},ensure_ascii=False)
 doc=f'''<!doctype html><html lang="en-AU"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{e(title)}</title><meta name="description" content="{e(description)}"><meta name="robots" content="{robots}"><link rel="canonical" href="{e(ORIGIN+path)}"><meta name="theme-color" content="#3556db"><meta property="og:type" content="website"><meta property="og:locale" content="en_AU"><meta property="og:site_name" content="Barmil Care Services"><meta property="og:title" content="{e(title)}"><meta property="og:description" content="{e(description)}"><meta property="og:url" content="{e(ORIGIN+path)}"><meta property="og:image" content="{ORIGIN}/assets/hero-home-support.webp"><meta property="og:image:alt" content="Illustrative scene of support at home"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="{e(title)}"><meta name="twitter:description" content="{e(description)}"><meta name="twitter:image" content="{ORIGIN}/assets/hero-home-support.webp"><link rel="icon" href="/assets/favicon.png" type="image/png"><link rel="apple-touch-icon" href="/assets/apple-touch-icon.png"><link rel="preload" href="/assets/jakarta-700.woff" as="font" type="font/woff" crossorigin><link rel="stylesheet" href="/styles.css"><script type="application/ld+json">{schema_json}</script><script src="/app.js" defer></script></head><body>{header(path)}<main id="main">{breadcrumbs(crumbs) if crumbs else ''}{body}</main>{footer()}</body></html>'''
 file=OUT/'index.html' if path=='/' else OUT/path.strip('/')/'index.html'
 file.parent.mkdir(parents=True,exist_ok=True);file.write_text(doc)
 PAGES.append({'path':path,'title':title,'description':description,'noindex':noindex,'primary':TARGETS.get(path,{}).get('primary','')})

def build_home():
 cats=[('At home','Disability support services for everyday routines, in the place you feel most familiar.','home'),('In the community','Practical assistance to get out, take part and feel connected.','people'),('Building independence','Time and support to practise skills and work towards your goals.','grow')]
 cards=''
 for cat,desc,ic in cats:
  cards+=f'<article class="category-card"><span class="icon-box">{icon(ic)}</span><h3>{e(cat)}</h3><p>{desc}</p><ul>'+''.join('<li>'+link(service_url(s),s['short'],'',True)+'</li>' for s in SERVICES if s['category']==cat)+'</ul></article>'
 body=f'''<section class="hero"><div class="container hero-grid"><div><div class="eyebrow">Your life. Your Canberra.</div><h1>Your NDIS provider in Canberra,<br><em>with you at the centre.</em></h1><p class="lead">Barmil Care Services is an NDIS provider in Canberra, offering disability support services for daily routines, community life and learning new skills. Tell us what would make your day easier.</p>{cta_actions('Let’s talk about you')}<p class="hero-caption">{icon('pin')}Supporting people across Canberra, ACT</p></div><div class="hero-media"><img class="hero-main" src="/assets/hero-home-support.webp" width="1200" height="900" alt="A wheelchair user and another woman smiling together at home" fetchpriority="high"><img class="hero-inset" src="/assets/community-picnic.webp" width="1200" height="900" alt="A group sharing a meal outdoors"><div class="photo-note"><strong>Support that starts with listening.</strong>Your goals guide the conversation.</div></div></div></section>
 <div class="intro-strip"><div class="container strip-grid">{''.join(f'<div class="strip-item">{icon(ic)}<div><strong>{a}</strong><span>{b}</span></div></div>' for ic,a,b in [('home','At home','Practical help with daily life'),('people','In your community','Support to connect and participate'),('grow','At your pace','Space to build skills and confidence')])}</div></div>
 <section class="section"><div class="container"><div class="section-heading"><div><div class="eyebrow" style="margin-bottom:18px">Find your support</div><h2>Everyday support.<br>Meaningful possibilities.</h2></div>{link('/services','Explore all ten services','text-link')}</div><div class="category-grid">{cards}</div></div></section>
 <section class="section white"><div class="container split"><img class="split-photo" src="/assets/about-support-team.webp" width="1024" height="1024" alt="Two women sitting together at a dining table" loading="lazy"><div class="split-content"><div class="eyebrow">The Barmil approach</div><h2>We start with a person.<br>We start with you.</h2><p class="lead">Choosing an NDIS provider in Canberra is personal. You deserve a conversation about your life, your preferences and what good support looks like to you.</p><div class="value-list">{''.join(f'<div class="value">{icon("check")}<div><h3>{a}</h3><p>{b}</p></div></div>' for a,b in [('Your choices come first','Tell us how you like things done, who you want involved and what you want to work towards.'),('Clear, practical conversations','We discuss the service, availability and arrangements before support starts.'),('Support across Canberra','From everyday routines at home to participating in local community life.')])}</div><div class="actions">{link('/about','Get to know Barmil','btn secondary',True)}</div></div></div></section>
 <section class="section"><div class="container"><div class="section-intro"><div class="eyebrow">Getting started</div><h2>You don’t need to have<br>all the answers.</h2><p class="lead">A first conversation is enough to begin exploring your options.</p></div><div class="steps">{''.join(f'<article class="step"><span class="step-num">0{i}</span><h3>{a}</h3><p>{b}</p></article>' for i,(a,b) in enumerate([('Tell us what matters','Share your goals, your Canberra suburb and the tasks or activities you would like support with.'),('Explore the right support','We discuss suitability, current availability, your plan arrangements and any questions you have.'),('Agree on a way forward','Understand the service and costs, then decide on the arrangements that work for you.')],1))}</div></div></section>
 <section class="section coverage"><div class="container split"><div><div class="eyebrow">Close to everyday life</div><h2>Across Canberra.<br>Around your routine.</h2><p>As an NDIS provider serving Canberra, we discuss support around your suburb and routine. Tell us the assistance you need so we can explore suitable arrangements.</p><div class="actions">{link('/service-areas','See Canberra service areas','btn light',True)}</div></div><div><div class="districts">{''.join(link('/service-areas#'+a.lower().replace(' ','-'),a) for a,b in AREAS)}</div><p class="area-note">Service availability and schedules are confirmed individually.</p></div></div></section>
 <section class="section white"><div class="container faq-grid"><div><div class="eyebrow" style="margin-bottom:18px">A few helpful answers</div><h2>Let’s make the<br>next step clearer.</h2><p class="lead">Questions are welcome. Here are a few places to start.</p><div class="actions">{link('/faqs','Read all FAQs','text-link')}</div></div>{faq_html(GLOBAL_FAQS[:4])}</div></section>'''
 write_page('/','NDIS Provider Canberra | Barmil Care Services','NDIS provider in Canberra offering personal care, household tasks, transport, community participation and life skills. Explore support with Barmil.',body)

def build_service(s):
 w,h,alt=IMAGE_INFO[s['image']]
 comparison=('<p>'+e(s['distinction'])+'</p>') if s.get('distinction') else ''
 context='<p class="service-context">'+ ' · '.join(link(p,t,'text-link') for p,t in s.get('contextLinks',[]))+'</p>'
 body=f'''<section class="page-hero"><div class="container hero-grid"><div><div class="eyebrow">{e(s['category'])} · Canberra</div><h1>{e(s['h1'])}</h1><p class="lead">{e(s['intro'])}</p>{cta_actions()}</div><img class="service-photo" src="/assets/{s['image']}" width="{w}" height="{h}" alt="{e(alt)}" decoding="async" fetchpriority="high"></div></section><section class="section white"><div class="container detail-grid"><div class="detail-body"><h2>{e(s['leadHeading'])}</h2>{''.join('<p>'+e(p)+'</p>' for p in s['body'])}{comparison}{context}<div class="subsection"><div class="eyebrow" style="margin-bottom:16px">Practical possibilities</div><h2>What support can involve</h2><div class="include-grid">{''.join(f'<div class="include-item"><h3>{e(a)}</h3><p>{e(b)}</p></div>' for a,b in s['includes'])}</div></div><div class="subsection"><h2>Let’s discuss the right arrangement.</h2><p class="muted">{e(s['process'])}</p><div class="note">{e(s['boundary'])}</div><p class="muted">We serve Canberra, including Belconnen, Gungahlin, North and South Canberra, Woden Valley, Weston Creek, Tuggeranong and the Molonglo Valley. {link('/service-areas','Explore our service areas','text-link')}.</p></div><div class="subsection"><h2>Your questions</h2>{faq_html(s['faqs'])}</div></div><aside class="sidebar"><h2>Talk it through<br>with Barmil.</h2><p>Tell us your Canberra suburb and the support you’re looking for.</p>{link('/contact','Make an enquiry','btn',True)}{link('tel:'+B['phoneHref'],B['phone'],'phone-link')}<p class="small">{e(B['hours'])}</p><div class="side-links">{link('/services','Explore all services')}{link('/ndis-supports','Understanding NDIS supports')}{link('/faqs','More questions and answers')}</div></aside></div></section><section class="section"><div class="container"><div class="section-intro"><div class="eyebrow">Other ways we can help</div><h2>Support that fits together.</h2></div><div class="service-grid">{''.join(card(BY_SLUG[k]) for k in s['related'])}</div></div></section>'''
 write_page(service_url(s),s['title'],s['description'],body,[('/services','Our services'),(None,s['name'])],s)

def build_other_pages():
 body=compact_hero('NDIS services in Canberra, built around your life.','Explore your options','Explore ten NDIS services in Canberra with Barmil Care Services. Compare help at home, participation in the community and support to build skills, then talk to us about the arrangements.')+f'''<section class="section white" style="padding-top:48px"><div class="container"><h2>Explore our ten support services.</h2><div class="filters" role="group" aria-label="Filter services">{''.join(f'<button class="filter" data-category="{cat}" aria-pressed="{str(i==0).lower()}">{cat}</button>' for i,cat in enumerate(['All services','At home','In the community','Building independence']))}</div><p class="sr-only" id="filter-status" aria-live="polite">10 services shown</p><div class="service-grid filterable">{''.join(card(s) for s in SERVICES)}</div><div class="note">These NDIS support services in Canberra have different purposes. Daily living assistance helps with routines; life skills development focuses on learning. Community access, shared group activities and tailored innovative participation also offer different approaches. Tell us about your goal so we can discuss a suitable option.</div></div></section>'''
 write_page('/services','NDIS Services Canberra | Barmil Care Services','Explore ten NDIS services in Canberra, including personal care, cleaning, transport, community participation, shared living assistance and life skills.',body,[(None,'Our services')])
 body=compact_hero('About Barmil Care Services in Canberra','Our approach','Barmil Care Services supports people with disability across Canberra. We focus on practical assistance that makes sense in your life, with your choices guiding the conversation.')+f'''<section class="section white"><div class="container split"><img class="split-photo" src="/assets/about-support-team.webp" width="1024" height="1024" alt="Two women sitting together at a dining table" loading="lazy"><div><div class="eyebrow" style="margin-bottom:20px">Why we’re here</div><h2>Life is personal.<br>Your support should be too.</h2><p class="muted">Everyone has their own routines, relationships and idea of a good day. We begin by asking about yours. What do you enjoy? What has become difficult? What would you like to do more independently?</p><p class="muted">Barmil Care Services provides disability support across Canberra through ten confirmed service areas: assistance at home, participation in the community and learning practical skills. You can enquire about one type of support or discuss how different services might fit together.</p><p class="muted">We serve the whole of Canberra. Your suburb, the support required and current availability help shape the arrangements we discuss with you.</p>{cta_actions('Have a conversation')}</div></div></section><section class="section"><div class="container"><div class="section-intro"><div class="eyebrow">What guides the conversation</div><h2>Your voice belongs<br>in every decision.</h2></div><div class="steps">{''.join(f'<article class="step"><span class="icon-box">{icon(ic)}</span><h3>{a}</h3><p>{b}</p></article>' for ic,a,b in [('heart','Respect your preferences','Tell us what matters, how you communicate and who you want involved in planning your support.'),('chat','Make arrangements clear','Ask about suitability, support tasks, timing and costs before agreeing on a service.'),('grow','Make room for your goals','Your priorities may change. Keep talking with us about what is working and what you would like to adjust.')])}</div></div></section>'''
 write_page('/about','About Barmil Care Services | Canberra Disability Support','Get to know Barmil Care Services, supporting people with disability across Canberra with everyday assistance, community participation and life skills.',body,[(None,'About us')])
 body=compact_hero('Canberra NDIS service areas','Local support','Barmil’s Canberra NDIS service areas cover the city’s districts, from Belconnen and Gungahlin to Woden Valley, Weston Creek and Tuggeranong. Share your suburb and the support you need so we can discuss availability.')+f'''<section class="section white"><div class="container"><div class="area-grid">{''.join(f'<article class="area-card" id="{a.lower().replace(" ","-")}"><h2>{a}</h2><p>{b}</p><small>Enquire about support in your suburb.</small></article>' for a,b in AREAS)}</div><div class="note">These are service areas, not office or centre locations. Individual services, schedules and travel arrangements are confirmed when you enquire. For requests outside Canberra, please contact us before making arrangements.</div></div></section><section class="section"><div class="container faq-grid"><div><div class="eyebrow" style="margin-bottom:20px">Local support</div><h2>Start with your suburb.<br>Then tell us about you.</h2><p class="lead">For NDIS support in Canberra, start with the type of assistance you need and where it will take place. We discuss travel, access requirements and timing for each arrangement.</p>{cta_actions()}</div>{faq_html([GLOBAL_FAQS[0],('My suburb is not listed. Can I still enquire?','Yes. The examples above are not an exhaustive suburb list. Barmil serves Canberra, so tell us your location and we can discuss suitable arrangements.'),('Can you support someone outside Canberra?','Our confirmed service area is Canberra. Please contact us to discuss any request outside this area before making arrangements.')])}</div></section>'''
 write_page('/service-areas','Canberra NDIS Service Areas | Barmil Care Services','NDIS support across Canberra: Belconnen, Gungahlin, Woden, Weston Creek, Tuggeranong, Molonglo Valley and North and South Canberra. Enquire with Barmil.',body,[(None,'Canberra service areas')])
 body=compact_hero('Understanding NDIS supports in Canberra','A practical guide','Understanding NDIS supports in Canberra starts with what you need help doing. This guide explains the differences between Barmil’s services so you can prepare questions and choose the support to discuss.')+f'''<section class="section white"><div class="container"><div class="guide-grid"><article class="guide-card"><h2>Assistance with everyday life</h2><p>Help with tasks you currently need assistance to complete, such as personal routines or essential household jobs.</p><ul><li>{link('/services/assist-personal-activities','Personal care')}</li><li>{link('/services/household-tasks','Household tasks')}</li><li>{link('/services/daily-tasks-shared-living','Daily tasks and shared living')}</li></ul></article><article class="guide-card"><h2>Learning everyday skills</h2><p>Support to practise a skill over time, rather than simply having a task done for you.</p><ul><li>{link('/services/development-life-skills','Life skills development')}</li><li>{link('/services/assist-life-stage-transition','Life stage and transition support')}</li><li>{link('/services/accommodation-tenancy','Accommodation and tenancy assistance')}</li></ul></article><article class="guide-card"><h2>Participating in your community</h2><p>Assistance with taking part in activities you choose. Individual support, group programs and tailored participation have different purposes.</p><ul><li>{link('/services/participate-community','Community participation')}</li><li>{link('/services/group-centre-activities','Group activities')}</li><li>{link('/services/innovative-community-participation','Innovative community participation')}</li></ul></article><article class="guide-card"><h2>Travelling to what matters</h2><p>Discuss the journey, your access requirements and any assistance you need at your destination. Confirm what is included before making a booking.</p><ul><li>{link('/services/assist-travel-transport','Travel and transport assistance')}</li></ul></article></div><div class="editorial" style="margin-top:65px"><h2>Using this NDIS support guide</h2><p>If you are comparing support options in Canberra, choose NDIS supports by their purpose. Assistance with a task, learning to do it, attending an activity and joining a group can require different arrangements.</p><h2>Four things to clarify before starting</h2><ol><li><strong>Your goal:</strong> the routine, task or activity you want help with.</li><li><strong>The service:</strong> what support is being offered and whether it suits your needs.</li><li><strong>The arrangements:</strong> timing, availability, location and the people involved.</li><li><strong>The costs:</strong> support time, travel and any other charges, along with how payment will be managed.</li></ol><h2>Check your individual funding arrangements.</h2><p>A service being listed on this website does not mean it is automatically funded for every participant. Your plan and disability-related needs determine which supports may be appropriate. Ask for clarification before agreeing to services.</p><p>Accommodation and tenancy assistance is different from supplying SDA housing. Daily tasks in a shared home do not automatically mean a SIL arrangement. These terms describe different types of support.</p><p>For current scheme information, visit the <a href="https://www.ndis.gov.au/participants">official NDIS participant website</a>. For provider registration information, visit the <a href="https://www.ndiscommission.gov.au/">NDIS Quality and Safeguards Commission</a>.</p></div></div></section>'''
